{
  "World_Setting": {
    "world_status": {
      "name": "地球 - 星辉纪元",
      "era": "公元2075年",
      "technology_level": "近未来科技（高科技战斗装备、人工智能、能量驱动的都市与武器，结合魔法能量网络）",
      "magic_system": "星辉魔法（基于光、暗、火、冰、雷、风六元素，以及灵魂共鸣与合体魔法）",
      "description": "在2075年的地球，科技与魔法融合，形成了高度发达的都市文明。魔法战姬（Stellar Senshi）是人类对抗虚空侵蚀者的核心力量，这些战姬通过灵魂共鸣与高科技战斗装甲作战，守护星辉网络——全球能量与魔法的支柱。虚空侵蚀者是暗元素滋生的异次元威胁，定期从空间裂隙入侵，破坏城市与星辉节点。战姬与指挥官通过契约链接，探索裂隙、回收神器、封印虚空，维护世界的平衡。",
      "condition": "都市繁荣与虚空威胁并存，战姬小队与指挥官协同作战，科技与魔法对抗裂隙入侵，星辉网络的稳定决定人类文明的存续",
      "key_elements": [
        "星辉魔法分为元素魔法（操控六元素）与灵魂共鸣（战姬与指挥官的契约、战姬间的合体魔法，解锁强大形态）",
        "魔法战姬由星辉核心选出，需穿戴高科技装甲，与指挥官建立灵魂链接以提升战力",
        "虚空侵蚀者为暗元素实体，从裂隙入侵，破坏星辉节点，需战姬以合体魔法或古代神器封印",
        "星辉网络是全球能量与魔法传输系统，连接星辉塔与都市，提供战姬战斗所需的能量",
        "裂隙遗迹为古代文明遗留，藏有神器与星辉技术秘密，吸引战姬与敌对势力争夺"
      ]
    },
    "factions": {
      "key_factions": [
        {
          "name": "星辉联盟",
          "description": "全球联合组织，管理星辉网络与战姬部队，负责对抗虚空侵蚀者，维护都市和平。总部位于新东京，拥有最先进的星辉科技。"
        },
        {
          "name": "裂隙掠夺者",
          "description": "叛逃战姬与科学家组成的地下势力，试图利用虚空能量与裂隙神器谋取权力，与星辉联盟对抗。"
        },
        {
          "name": "星辉学院",
          "description": "培养战姬与指挥官的机构，遍布全球，提供魔法与科技训练，挖掘潜力者并分配至战姬小队。"
        },
        {
          "name": "虚空教团",
          "description": "崇拜虚空侵蚀者的神秘组织，试图通过仪式扩大裂隙，削弱星辉网络，追求暗元素的‘净化’。"
        }
      ]
    },
    "races": {
      "description": "地球主要由人类构成，少量异族血脉者因古代魔法实验存续，影响战姬天赋与文化。",
      "races": [
        {
          "name": "人类",
          "description": "地球主导种族，科技与魔法天赋兼备，居住在高科技都市，战姬多为人类，擅长多样化的元素魔法与战术。"
        },
        {
          "name": "星裔",
          "description": "拥有古代异族血脉的人类后裔，稀少且天赋异禀，擅长光或暗魔法，常成为顶级战姬或指挥官，隐居都市或学院。"
        }
      ]
    },
    "senshi_and_void": {
      "description": "魔法战姬与虚空侵蚀者是星辉纪元的核心对立，象征科技与魔法的守护和暗元素的毁灭。战姬由星辉核心选出，虚空侵蚀者周期性入侵，双方对抗决定地球的命运。",
      "key_elements": [
        {
          "name": "魔法战姬",
          "description": "由星辉核心选出的天赋者，穿戴高科技战斗装甲，掌握元素魔法与合体能力。需与指挥官建立灵魂链接，组成小队对抗虚空侵蚀者，探索裂隙遗迹以获取神器。"
        },
        {
          "name": "虚空侵蚀者",
          "description": "暗元素与异次元能量的化身，从空间裂隙入侵，破坏星辉节点与都市。力量诡异多变，需战姬以合体魔法或神器封印或消灭。"
        }
      ]
    },
    "regions": {
      "description": "地球分为五大核心区域，各具科技与魔法特色，星辉节点与裂隙分布影响战姬任务与势力格局。",
      "regions": [
        {
          "name": "新东京",
          "description": "星辉联盟总部所在地，科技与魔法融合的超级都市，星辉塔林立，裂隙遗迹多为古代实验设施，战姬活跃。"
        },
        {
          "name": "极光海湾",
          "description": "北美沿海的高科技港湾，光与雷魔法浓郁，星辉学院分部众多，裂隙常出现在海底遗迹，适合高机动作战。"
        },
        {
          "name": "沙漠枢纽",
          "description": "中东地区的能量中枢，火与风元素活跃，星辉节点密集，遗迹多为古代神器库，裂隙掠夺者活动频繁。"
        },
        {
          "name": "冰霜群岛",
          "description": "北欧的岛屿群，冰与暗魔法弥漫，星辉塔少但能量纯净，裂隙隐藏在冰川遗迹，虚空教团据点隐秘。"
        },
        {
          "name": "曙光雨林",
          "description": "南美热带雨林，风与光元素充沛，星辉网络覆盖较弱，裂隙遗迹为古代祭坛，战姬需面对复杂地形与妖兽。"
        }
      ]
    }
  }
}

